<template><section class="demo-shell"><search><form class="toolbar" action="" method="get" @submit.prevent="search"><label for="filter-query">商品名称或 SKU<input id="filter-query" name="q" type="search" v-model="query" maxlength="100"></label><label for="filter-category">品类<select id="filter-category" name="category" v-model="category"><option value="">全部</option><option>数码配件</option><option>家居用品</option><option>办公文具</option></select></label><a-button html-type="submit"  @click="">查询</a-button><a-button html-type="button"  @click="reset">重置</a-button></form></search><div class="actions"><a-button html-type="button" id="create-record" @click="create">新增商品</a-button></div><form action="" method="post" @submit.prevent="save" v-if="editing" class="native-form"><fieldset class="edit-form"><legend>编辑商品</legend><label for="record-name">商品名称（必填）<input id="record-name" name="name" v-model="editing.name" required maxlength="60" pattern=".*\S.*"></label><label for="record-category">品类<select id="record-category" name="category" v-model="editing.category"><option>数码配件</option><option>家居用品</option><option>办公文具</option></select></label><label for="record-status">上架状态<select id="record-status" name="status" v-model="editing.status"><option>在售</option><option>下架</option></select></label><label for="record-stock">库存（件，必填）<input id="record-stock" name="stock" type="number" v-model.number="editing.stock" min="0" max="999999" step="1" required></label><div class="actions"><button type="submit" class="primary">保存商品</button><button type="button" @click="cancelEdit">取消编辑</button></div></fieldset></form><p role="status" class="summary">{{notice}}</p><div class="split"><section><div class="table-scroll" tabindex="0" role="region" aria-label="演示数据，可横向滚动"><a-table :data-source="visibleRows" :columns="columns" :pagination="false" row-key="id" aria-label="演示数据表"><template #bodyCell="{column,record}"><div v-if="column.key==='actions'" class="actions"><button type="button" @click="choose(record)" :aria-label="'选择 '+record.code">选择</button><button type="button" @click="edit(record)" :aria-label="'编辑 '+record.code">编辑</button><button type="button" @click="remove(record)" :aria-label="'删除 '+record.code">删除</button></div><span v-else>{{record[column.dataIndex]}}</span></template></a-table></div><nav class="pagination" aria-label="演示数据分页"><button type="button" :disabled="page===1" @click="previous">上一页</button><span>第 {{page}} / {{pageCount}} 页 · {{filtered.length}} 件商品</span><button type="button" :disabled="page===pageCount" @click="next">下一页</button></nav></section><content-area :rows="filtered" @select="choose"/></div></section></template><script>import options from './demo.mjs';export default options;</script>
